fn run_m4_app() {
	mut st := Thread_m4_app_state{} // small + carries the FB field defaults: stack is right
	mut sched := &g_sched_m4_app // module-sized: lives in bss, not this lifetime frame
	sched.every(10000, handler_m4_m4_load_on_10ms, &st)
	tick_us := u64(1000)
	sched.set_trace_hook(trace_fb_hook_m4_app, unsafe { nil })
	for {
		t0 := C.board_now_us()
		sched.run_profiled(trace_clock)
		t1 := C.board_now_us()
		if t1 - t0 > tick_us { // pass exceeded its tick budget -> overrun
			sched.mark_overrun()
		}
		C.duo_trace_service() // ~one poll per tick: plenty for the dump handshake
		C.duo_load_pub(1, u16(sched.load_permille() + g_sched_m4_stress.load_permille()))
		C.duo_bulk_produce() // cross-core bulk producer (platform-owned pool)
		C.duo_layout_publish() // REPUBLISH per tick: the owner retracts the id at ITS
		// boot (SRAM survives an owner-only reset — a retained id + retained channels
		// would replay one stale frame); a live satellite restores it within a tick
		C._tx_thread_sleep(u32(1))
	}
}

